#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{"crash_cause":"UArenaScoreTracker* ScoreTracker was a raw UObject pointer without UPROPERTY() in AArenaGameMode, so the garbage collector could not see it. The packaged Shipping build ran GC (log: LogGarbage: Collecting garbage: 412 objects purged), which purged the ScoreTracker object. The first goal then dereferenced the dangling pointer in UArenaScoreTracker::AddPoints() (ArenaScoreTracker.cpp:18), causing EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff. In the editor GC pressure/timing differs, so it did not reproduce. Fix: made ScoreTracker a UPROPERTY() TObjectPtr<UArenaScoreTracker> so GC tracks it.","no_colors_cause":"The HUD palette asset /Game/Data/Palettes/DA_Primary is loaded at runtime with LoadObject, but packaging settings had bCookAll=False and the /Game/Data/Palettes directory was neither in MapsToCook nor DirectoriesToAlwaysCook, so the asset was never cooked into the pak. LoadObject failed (log: Could not find file for package /Game/Data/Palettes/DA_Primary), the game fell back to gray (Palette is null, using fallback gray), so the arena had no colors. Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."}
